    "contentId": "pf2e:spell:spells-srd:whirlpool",
    "locale": "pt-BR",
    "sourceTranslatableHash": "sha256:30bc2f58d81aed8764a11adb68f3e2b5bb8f9740a92d850cb12389e33f3b737b",
